<?php
namespace Tests\Feature\Finance;
use App\Models\AcademicYear; use App\Models\Fee; use App\Models\User; use Database\Seeders\RolesAndPermissionsSeeder; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
abstract class ModernFinanceCatalogTestCase extends TestCase { use RefreshDatabase; protected User $user; protected AcademicYear $year; protected function setUp():void{parent::setUp();(new RolesAndPermissionsSeeder)->run();$this->user=User::factory()->create(['is_active'=>true]);$this->user->assignRole('accountant');$this->year=AcademicYear::create(['name'=>'2026/2027','start_date'=>'2026-08-01','end_date'=>'2027-06-30','is_active'=>true]);} protected function fee():Fee{return Fee::create(['name_ru'=>'Транспорт','category'=>'transport','type'=>'service','amount'=>0,'is_active'=>true]);} protected function tariff(Fee $fee,array $x=[]):array{return array_merge(['fee_id'=>$fee->id,'academic_year_id'=>$this->year->id,'amount'=>'1000.00','start_date'=>'2026-09-01','end_date'=>'2026-09-30','is_active'=>1,'change_reason'=>'Новая стоимость'], $x);} }
